import bpy, mathutils
roots = {}
for root in sorted((obj for obj in bpy.context.scene.objects if obj.type == 'EMPTY' and obj.name.startswith('location_')), key=lambda obj: obj.name):
    meshes = [obj for obj in root.children_recursive if obj.type == 'MESH']
    corners = [obj.matrix_world @ mathutils.Vector(corner) for obj in meshes for corner in obj.bound_box]
    bounds = None if not corners else {'min': [round(min(point[index] for point in corners), 5) for index in range(3)], 'max': [round(max(point[index] for point in corners), 5) for index in range(3)]}
    roots[root.name] = {'source': root.get('source'), 'assetFile': root.get('assetFile'), 'meshCount': len(meshes), 'bounds': bounds}
result = {'locationCount': len(roots), 'tripoRoots': sum(value['source'] == 'magnific-tripo' for value in roots.values()), 'fallbackRoots': sum(value['source'] != 'magnific-tripo' for value in roots.values()), 'roots': roots, 'imageCount': len(bpy.data.images), 'materialCount': len(bpy.data.materials)}
